        c.addView(actionButton("⇧  RAPORU DIŞA AKTAR / PAYLAŞ", cyan) { exportDiagnosticReport() })
        addGap(c, 7)
        c.addView(actionButton("⌂  ANA SAYFA", blue) { showHome() })
    }

    private fun exportDiagnosticReport() {
        val report = buildString {
            appendLine("EFE MOTO - TEŞHİS / SERVİS RAPORU")
            appendLine("Tarih: ${SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale("tr", "TR")).format(Date())}")
            appendLine("Müşteri: ${serviceCustomer.ifBlank { "—" }}")
            appendLine("Araç / Plaka: ${servicePlate.ifBlank { "—" }}")
            appendLine("Şikâyet / Not: ${serviceComplaint.ifBlank { "—" }}")
            appendLine("Arıza kodları: ${faults.joinToString().ifBlank { "Kayıtlı arıza yok / henüz taranmadı" }}")
            appendLine("Akıllı risk puanı: $currentRiskScore / 100")
            appendLine("CANLI ECU VERİLERİ")
            if (liveValues.isEmpty()) appendLine("Canlı veri snapshot'ı alınmadı.")
            else liveValues.forEach { (key, value) -> appendLine("$key = ${"%.2f".format(Locale.US, value)}") }
            appendLine()
            appendLine("İŞLEM GEÇMİŞİ")
            if (logs.isEmpty()) appendLine("Henüz kayıt yok.") else logs.forEach { appendLine(it) }
        }
        val send = Intent(Intent.ACTION_SEND).apply {
            type = "text/plain"
            putExtra(Intent.EXTRA_SUBJECT, "EFE MOTO Teşhis Raporu")
            putExtra(Intent.EXTRA_TEXT, report)
        }
        try { startActivity(Intent.createChooser(send, "EFE MOTO raporunu kaydet / paylaş")) }
        catch (e: Exception) { Toast.makeText(this, "Rapor dışa aktarılamadı: ${e.message}", Toast.LENGTH_LONG).show() }
    }

    // ---------------- Viecar / ELM327 Wi-Fi ----------------

    private fun createWifiBoundSocket(): Socket {
        val manager = getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager
        @Suppress("DEPRECATION")
        val candidates = (listOfNotNull(manager.activeNetwork) + manager.allNetworks.toList()).distinct()
        val wifiNetwork = candidates.firstOrNull { network ->
            manager.getNetworkCapabilities(network)?.hasTransport(NetworkCapabilities.TRANSPORT_WIFI) == true
        } ?: throw IllegalStateException(
            "Wi‑Fi ağı bulunamadı. Önce telefonun Wi‑Fi ayarlarından Viecar adaptörünün ağına bağlanın."
        )
        return wifiNetwork.socketFactory.createSocket()
    }

    private fun ensureConnected(onExchange: ((String, String) -> Unit)? = null) {
        if (simulationMode) throw IllegalStateException("Simülasyon açık. Gerçek ECU komutu için ana sayfadan EVET ile gerçek teşhisi başlatın.")
        if (connected && socket?.isConnected == true && socket?.isClosed == false) return
        closeAdapter()
        supportedPidSet.clear()
        // Bind the TCP socket to the phone's Wi-Fi network so Android does not route
        // the connection through mobile data when the Viecar hotspot has no internet.
        val s = createWifiBoundSocket()
        s.tcpNoDelay = true
        s.connect(InetSocketAddress("192.168.0.10", 35000), 7000)
        s.soTimeout = 3500
        socket = s

        fun exchange(command: String, timeoutMs: Int = 3000): String {
            return try {
                val response = elm(command, timeoutMs)
                onExchange?.invoke(command, response)
                response
            } catch (e: Exception) {
                onExchange?.invoke(command, "ERROR: ${e.message}")
                throw e
            }
        }

        // ELM327 initialization. Commands are reported to the communication test when requested.
        exchange("ATZ", 5000)
        exchange("ATE0")
        exchange("ATL0")
        exchange("ATS0")
        exchange("ATH0")
        exchange("ATSP0")
        val test = exchange("0100", 7000)
        val testHex = test.filter { it in "0123456789ABCDEF" }
        if (!testHex.contains("4100")) {
            closeAdapter()
            throw IllegalStateException("Viecar TCP bağlantısı açıldı ancak ECU'dan geçerli 41 00 yanıtı alınamadı: ${test.ifBlank { "(boş yanıt)" }}")
        }
        connected = true
        mainHandler.post { statusLine?.apply { text = "● VIECAR / ECU BAĞLI"; setTextColor(green) } }
        log("Viecar Wi‑Fi bağlantısı kuruldu")
    }

    @Synchronized
    private fun elm(command: String, timeoutMs: Int = 3000): String {
        val s = socket ?: throw IllegalStateException("Adaptör bağlı değil")
        if (s.isClosed || !s.isConnected) throw IllegalStateException("Adaptör bağlantısı kapalı")
        val out = s.getOutputStream()
        val input = s.getInputStream()
        s.soTimeout = timeoutMs
        // Discard only stale bytes left by a previous timed-out ELM response.
        try {
            while (input.available() > 0) input.read()
        } catch (_: Exception) { }
        out.write((command.trim() + "\r").toByteArray(Charset.forName("US-ASCII")))
        out.flush()
        val result = ByteArrayOutputStream()
        val started = System.currentTimeMillis()
        try {
            while (System.currentTimeMillis() - started < timeoutMs) {
                val b = input.read()
                if (b < 0) break
                if (b == '>'.code) break
                result.write(b)
            }
        } catch (_: SocketTimeoutException) { }
        val response = result.toString("US-ASCII").replace("\u0000", "").trim().uppercase(Locale.US)
        lastRaw = response
        return response
    }

    private fun pidBytes(pid: String, timeoutMs: Int = 3000): List<Int>? {
        val response = elm("01$pid", timeoutMs)
        val compact = response.replace(Regex("[^0-9A-F]"), "")
        val marker = "41$pid"
        val at = compact.indexOf(marker)
        if (at < 0) return null
        val tail = compact.substring(at + marker.length)
        if (tail.length < 2) return null
        return tail.chunked(2).mapNotNull { it.takeIf { part -> part.length == 2 }?.toIntOrNull(16) }
    }

    private fun decodeDtcs(raw: String, positiveResponse: String = "43"): List<String> {
        val compact = raw.replace(Regex("[^0-9A-F]"), "")
        val index = compact.indexOf(positiveResponse)
        if (index < 0) throw IllegalStateException("ECU geçerli $positiveResponse arıza yanıtı göndermedi: ${raw.ifBlank { "(boş)" }}")
        val bytes = compact.substring(index + 2).chunked(2).filter { it.length == 2 }.mapNotNull { it.toIntOrNull(16) }
        val found = mutableListOf<String>()
        var i = 0
        while (i + 1 < bytes.size) {
            val a = bytes[i]
            val b = bytes[i + 1]
            if (a == 0 && b == 0) { i += 2; continue }
            val first = when ((a and 0xC0) shr 6) { 0 -> 'P'; 1 -> 'C'; 2 -> 'B'; else -> 'U' }
            val digit2 = (a and 0x30) shr 4
            val digit3 = a and 0x0F
            val digit4 = (b and 0xF0) shr 4
            val digit5 = b and 0x0F
            found.add("$first$digit2${digit3.toString(16).uppercase(Locale.US)}${digit4.toString(16).uppercase(Locale.US)}${digit5.toString(16).uppercase(Locale.US)}")
            i += 2
        }
        return found.distinct()
    }

    private fun closeAdapter() {
        connected = false
        try { socket?.close() } catch (_: Exception) { }
        socket = null
        mainHandler.post { statusLine?.apply { text = "● ADAPTÖR BAĞLI DEĞİL"; setTextColor(muted) } }
    }

    // ---------------- Custom graphics ----------------

    private inner class NeonBackdrop(context: android.content.Context) : View(context) {
        private val paint = Paint(Paint.ANTI_ALIAS_FLAG)
        override fun onDraw(canvas: Canvas) {
            super.onDraw(canvas)
            canvas.drawColor(bg)
            paint.shader = RadialGradient(width * .5f, height * .25f, width * .8f,
                intArrayOf(Color.rgb(0, 30, 85), bg), null, Shader.TileMode.CLAMP)
            canvas.drawRect(0f, 0f, width.toFloat(), height.toFloat(), paint)
            paint.shader = null
            paint.color = Color.argb(22, 0, 135, 255)
            paint.strokeWidth = dp(1).toFloat()
            var x = 0
            while (x < width) { canvas.drawLine(x.toFloat(), 0f, x.toFloat(), height.toFloat(), paint); x += dp(38) }
            var y = 0
            while (y < height) { canvas.drawLine(0f, y.toFloat(), width.toFloat(), y.toFloat(), paint); y += dp(38) }
        }
    }

    private inner class MotorcycleArtView(context: android.content.Context) : View(context) {
        private val p = Paint(Paint.ANTI_ALIAS_FLAG)
        override fun onDraw(canvas: Canvas) {
            super.onDraw(canvas)
            val w = width.toFloat(); val h = height.toFloat()
            p.shader = RadialGradient(w * .52f, h * .55f, w * .58f,
                intArrayOf(Color.rgb(0, 80, 210), Color.rgb(0, 20, 65), Color.TRANSPARENT), null, Shader.TileMode.CLAMP)
            canvas.drawRect(0f, 0f, w, h, p); p.shader = null
            // Electric rays behind the motorcycle
            p.color = Color.argb(95, 0, 160, 255); p.strokeWidth = dp(1).toFloat()
            for (i in 0..23) {
                val a = i * (Math.PI * 2 / 24)
                canvas.drawLine(w * .5f, h * .56f, w * .5f + cos(a).toFloat() * w * .47f,
                    h * .56f + sin(a).toFloat() * h * .42f, p)
            }
            val wheelY = h * .75f
            val leftX = w * .22f
            val rightX = w * .79f
            val radius = min(w, h) * .145f
            // Wheels
            for (x in listOf(leftX, rightX)) {
                p.color = Color.BLACK; p.style = Paint.Style.FILL; canvas.drawCircle(x, wheelY, radius, p)
                p.color = cyan; p.style = Paint.Style.STROKE; p.strokeWidth = dp(3).toFloat(); p.setShadowLayer(dp(13).toFloat(), 0f, 0f, blue)
                canvas.drawCircle(x, wheelY, radius, p); p.clearShadowLayer()
                p.color = Color.rgb(30, 75, 130); p.strokeWidth = dp(2).toFloat(); canvas.drawCircle(x, wheelY, radius * .68f, p)
                for (j in 0..7) {
                    val a = j * Math.PI / 4
                    canvas.drawLine(x, wheelY, x + cos(a).toFloat() * radius * .66f, wheelY + sin(a).toFloat() * radius * .66f, p)
                }
                p.style = Paint.Style.FILL
            }
            // Motorcycle body silhouette / frame
            p.style = Paint.Style.STROKE; p.strokeCap = Paint.Cap.ROUND; p.strokeJoin = Paint.Join.ROUND
            p.strokeWidth = dp(12).toFloat(); p.color = Color.rgb(8, 28, 65)
            val frame = Path().apply {
                moveTo(leftX, wheelY); lineTo(w * .42f, h * .53f); lineTo(w * .66f, h * .52f); lineTo(rightX, wheelY)
                moveTo(w * .42f, h * .53f); lineTo(w * .5f, h * .73f); lineTo(w * .66f, h * .52f)
            }
            canvas.drawPath(frame, p)
            p.color = cyan; p.strokeWidth = dp(3).toFloat(); p.setShadowLayer(dp(9).toFloat(), 0f, 0f, blue); canvas.drawPath(frame, p); p.clearShadowLayer()
            // Tank and fairing
            p.style = Paint.Style.FILL
            val fairing = Path().apply {
                moveTo(w * .26f, h * .59f); lineTo(w * .36f, h * .43f); lineTo(w * .55f, h * .37f)
                lineTo(w * .69f, h * .42f); lineTo(w * .79f, h * .56f); lineTo(w * .69f, h * .62f)
                lineTo(w * .54f, h * .59f); lineTo(w * .42f, h * .66f); close()
            }
            p.color = Color.rgb(0, 35, 105); p.setShadowLayer(dp(12).toFloat(), 0f, 0f, blue); canvas.drawPath(fairing, p); p.clearShadowLayer()
            p.color = cyan; p.style = Paint.Style.STROKE; p.strokeWidth = dp(3).toFloat(); canvas.drawPath(fairing, p)
            p.color = Color.rgb(5, 20, 48); p.style = Paint.Style.FILL
            canvas.drawOval(w * .43f, h * .44f, w * .65f, h * .56f, p)
            p.color = Color.rgb(0, 115, 255); p.style = Paint.Style.STROKE; p.strokeWidth = dp(2).toFloat()
            canvas.drawOval(w * .43f, h * .44f, w * .65f, h * .56f, p)
            // Windscreen / handlebar / lights
            p.strokeWidth = dp(6).toFloat(); p.color = Color.rgb(90, 180, 255)
            canvas.drawLine(w * .52f, h * .38f, w * .57f, h * .27f, p)
            canvas.drawLine(w * .57f, h * .27f, w * .71f, h * .29f, p)
            canvas.drawLine(w * .69f, h * .31f, w * .82f, h * .34f, p)
            p.color = cyan; p.strokeWidth = dp(4).toFloat(); p.setShadowLayer(dp(11).toFloat(), 0f, 0f, cyan)
            canvas.drawLine(w * .70f, h * .34f, w * .79f, h * .39f, p); p.clearShadowLayer()
            p.style = Paint.Style.FILL
            p.color = Color.WHITE; canvas.drawCircle(w * .76f, h * .47f, dp(5).toFloat(), p)
            p.color = cyan; p.setShadowLayer(dp(12).toFloat(), 0f, 0f, cyan); canvas.drawCircle(w * .76f, h * .47f, dp(7).toFloat(), p); p.clearShadowLayer()
            p.color = muted; p.textSize = dp(13).toFloat(); p.typeface = Typeface.create("sans-serif-condensed", Typeface.BOLD)
            canvas.drawText("EFE MOTO  •  ECU DIAGNOSTIC", w * .5f - p.measureText("EFE MOTO  •  ECU DIAGNOSTIC") / 2, h * .96f, p)
        }
    }

    private inner class CircularProgressView(context: android.content.Context) : View(context) {
        var progress = 0
        private val p = Paint(Paint.ANTI_ALIAS_FLAG)
        override fun onDraw(canvas: Canvas) {
            super.onDraw(canvas)
            val cx = width / 2f; val cy = height / 2f; val r = min(width, height) * .36f
            p.style = Paint.Style.STROKE; p.strokeWidth = dp(15).toFloat(); p.strokeCap = Paint.Cap.ROUND
            p.color = Color.rgb(10, 38, 76); canvas.drawArc(cx-r, cy-r, cx+r, cy+r, -90f, 360f, false, p)
            p.color = cyan; p.setShadowLayer(dp(13).toFloat(), 0f, 0f, blue)
            canvas.drawArc(cx-r, cy-r, cx+r, cy+r, -90f, 360f * progress / 100f, false, p); p.clearShadowLayer()
            p.style = Paint.Style.FILL; p.color = white; p.textAlign = Paint.Align.CENTER
            p.typeface = Typeface.create("sans-serif-condensed", Typeface.BOLD); p.textSize = dp(39).toFloat()
            canvas.drawText("%$progress", cx, cy + dp(13), p)
        }
    }

    private inner class RpmGaugeView(context: android.content.Context) : View(context) {
        var value = -1
        private val p = Paint(Paint.ANTI_ALIAS_FLAG)

        override fun onDraw(canvas: Canvas) {
            super.onDraw(canvas)
            val w = width.toFloat()
            val h = height.toFloat()
            val cx = w / 2f
            val cy = h * 0.84f
            val r = min(w * 0.43f, h * 0.78f)
            val arc = RectF(cx - r, cy - r, cx + r, cy + r)

            // Deep blue instrument face and outer neon rim.
            p.style = Paint.Style.FILL
            p.shader = RadialGradient(cx, cy - r * 0.45f, r * 1.35f,
                intArrayOf(Color.rgb(10, 42, 92), Color.rgb(1, 9, 25), Color.BLACK),
                floatArrayOf(0f, 0.72f, 1f), Shader.TileMode.CLAMP)
            canvas.drawRoundRect(RectF(dp(5).toFloat(), dp(4).toFloat(), w - dp(5), h - dp(2).toFloat()), dp(13).toFloat(), dp(13).toFloat(), p)
            p.shader = null

            p.style = Paint.Style.STROKE
            p.strokeCap = Paint.Cap.ROUND
            p.strokeWidth = dp(13).toFloat()
            p.color = Color.rgb(13, 45, 84)
            canvas.drawArc(arc, 180f, 180f, false, p)
            p.color = cyan
            p.setShadowLayer(dp(12).toFloat(), 0f, 0f, blue)
            canvas.drawArc(arc, 180f, 180f, false, p)
            p.clearShadowLayer()
            p.color = red
            p.strokeWidth = dp(13).toFloat()
            p.setShadowLayer(dp(10).toFloat(), 0f, 0f, red)
            canvas.drawArc(arc, 330f, 30f, false, p)
            p.clearShadowLayer()

            // Major and minor scale marks, 0–12 x 1000 RPM.
            for (i in 0..24) {
                val angle = Math.toRadians(180.0 + i * 7.5)
                val major = i % 2 == 0
                val inner = r * if (major) 0.78f else 0.84f
                val outer = r * 0.94f
                p.strokeWidth = dp(if (major) 2 else 1).toFloat()
                p.color = if (i >= 20) red else if (major) white else Color.rgb(70, 120, 175)
                canvas.drawLine(
                    cx + kotlin.math.cos(angle).toFloat() * inner,
                    cy + kotlin.math.sin(angle).toFloat() * inner,
                    cx + kotlin.math.cos(angle).toFloat() * outer,
                    cy + kotlin.math.sin(angle).toFloat() * outer,
                    p
                )
            }

            p.style = Paint.Style.FILL
            p.textAlign = Paint.Align.CENTER
            p.typeface = Typeface.create("sans-serif-condensed", Typeface.BOLD)
            p.textSize = dp(13).toFloat()
            for (i in 0..6) {
                val angle = Math.toRadians(180.0 + i * 30.0)
                val labelRadius = r * 0.66f
                val x = cx + kotlin.math.cos(angle).toFloat() * labelRadius
                val y = cy + kotlin.math.sin(angle).toFloat() * labelRadius + dp(5)
                p.color = if (i == 6) red else white
                canvas.drawText((i * 2).toString(), x, y, p)
            }

            // Needle.
            val safeValue = value.coerceIn(0, 12000)
            val needleAngle = Math.toRadians(180.0 + (safeValue / 12000.0) * 180.0)
            val needleLength = r * 0.72f
            p.style = Paint.Style.STROKE
            p.strokeWidth = dp(4).toFloat()
            p.strokeCap = Paint.Cap.ROUND
            p.color = Color.WHITE
            p.setShadowLayer(dp(8).toFloat(), 0f, 0f, cyan)
            canvas.drawLine(cx, cy, cx + kotlin.math.cos(needleAngle).toFloat() * needleLength,
                cy + kotlin.math.sin(needleAngle).toFloat() * needleLength, p)
            p.clearShadowLayer()
            p.style = Paint.Style.FILL
            p.color = cyan
            canvas.drawCircle(cx, cy, dp(8).toFloat(), p)
            p.color = Color.WHITE
            canvas.drawCircle(cx, cy, dp(3).toFloat(), p)

            p.textAlign = Paint.Align.CENTER
            p.typeface = Typeface.create("sans-serif-condensed", Typeface.BOLD)
            p.color = white
            p.textSize = dp(35).toFloat()
            canvas.drawText(if (value >= 0) value.toString() else "—", cx, cy - dp(17), p)
            p.textSize = dp(16).toFloat()
            p.color = cyan
            canvas.drawText("RPM", cx, cy + dp(22), p)
        }
    }
